import { MeshBasicNodeMaterial } from 'three/webgpu';
import { color, mix, texture, uv } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, CircleGeometry } = ctx.THREE;
  const root = new Group();
  const ownedGeometries = [];
  const ownedMaterials = [];
  const loadedTextures = [];
  const timelines = [];

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const backdropGeometry = new PlaneGeometry(7, 6);
  const backdropMaterial = new MeshBasicNodeMaterial();
  backdropMaterial.colorNode = mix(
    color(colors.surface),
    color(colors.ink),
    uv().y
  );
  const backdrop = new Mesh(backdropGeometry, backdropMaterial);
  backdrop.position.set(3.2, -1, -2.5);
  root.add(backdrop);
  ownedGeometries.push(backdropGeometry);
  ownedMaterials.push(backdropMaterial);

  const shadowGeometry = new CircleGeometry(1.05, 48);
  const shadowMaterial = new MeshBasicNodeMaterial({
    color: colors.surface,
    transparent: true,
    opacity: 0.48,
    depthWrite: false
  });
  const shadow = new Mesh(shadowGeometry, shadowMaterial);
  shadow.scale.set(1.22, 0.42, 1);
  shadow.position.set(0, -0.58, -0.08);
  root.add(shadow);
  ownedGeometries.push(shadowGeometry);
  ownedMaterials.push(shadowMaterial);

  const cardGeometry = new PlaneGeometry(2.15, 1.34);
  const cardMaterial = new MeshBasicNodeMaterial({
    color: colors.surface,
    transparent: true
  });
  const card = new Mesh(cardGeometry, cardMaterial);
  card.position.set(0, 0, 0);
  root.add(card);
  ownedGeometries.push(cardGeometry);
  ownedMaterials.push(cardMaterial);

  card.onBeforeRender = (_renderer, _scene, camera) => {
    if (camera) card.quaternion.copy(camera.quaternion);
  };

  const imageUrl = config.imageUrl;
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((loadedTexture) => {
      if (root.userData.cleaned) {
        loadedTexture.dispose?.();
        return;
      }

      const image = loadedTexture.image;
      const imageWidth = image?.width || 512;
      const imageHeight = image?.height || 320;
      const region = config.atlasRegion ?? {
        x: 0,
        y: 0,
        width: 512,
        height: 320
      };

      loadedTexture.wrapS = ctx.THREE.ClampToEdgeWrapping;
      loadedTexture.wrapT = ctx.THREE.ClampToEdgeWrapping;
      loadedTexture.repeat.set(
        region.width / imageWidth,
        region.height / imageHeight
      );
      loadedTexture.offset.set(
        region.x / imageWidth,
        1 - (region.y + region.height) / imageHeight
      );

      if ('SRGBColorSpace' in ctx.THREE) {
        loadedTexture.colorSpace = ctx.THREE.SRGBColorSpace;
      }

      cardMaterial.map = texture(loadedTexture);
      cardMaterial.needsUpdate = true;
      loadedTextures.push(loadedTexture);
    }).catch(() => {});
  }

  const accentGeometry = new PlaneGeometry(0.56, 0.035);
  const accentMaterial = new MeshBasicNodeMaterial({
    color: colors.accent
  });
  const accent = new Mesh(accentGeometry, accentMaterial);
  accent.position.set(-0.68, -0.53, 0.12);
  root.add(accent);
  ownedGeometries.push(accentGeometry);
  ownedMaterials.push(accentMaterial);

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    const text = String(item.text ?? '');
    if (!text) continue;

    const typography = item.typography ?? {};
    const label = ctx.fontAtlas.createText(text, {
      fontSize: typography.fontSize ?? 39,
      color: colors.paper,
      align: 'left',
      maxWidthPx: 460
    });

    label.position.set(-0.83, -0.02, 0.16);
    root.add(label);
  }

  const cardContent = new Group();
  while (card.children.length) {
    cardContent.add(card.children[0]);
  }

  const entrance = gsap.timeline();
  entrance.fromTo(
    card.scale,
    { x: 0.96, y: 0.96, z: 0.96 },
    { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }
  );
  timelines.push(entrance);

  const primitiveResults = [];
  const primitives = config.cinematicPrimitives ?? [];
  for (const primitive of primitives) {
    const handler = ctx.primitives?.[primitive.name];
    if (typeof handler === 'function') {
      const result = handler(root, primitive.params ?? {});
      if (result) primitiveResults.push(result);
    }
  }

  root.userData.handlers = {};
  root.userData.cleanup = () => {
    if (root.userData.cleaned) return;
    root.userData.cleaned = true;

    for (const timeline of timelines) {
      timeline?.kill?.();
    }

    for (const result of primitiveResults) {
      result?.timeline?.kill?.();
      result?.cleanup?.();
    }

    for (const textureResource of loadedTextures) {
      textureResource.dispose?.();
    }

    for (const geometry of ownedGeometries) {
      geometry.dispose?.();
    }

    for (const material of ownedMaterials) {
      material.dispose?.();
    }
  };

  return root;
}
